   412→// parseCallExpression parses func(arg1, arg2)
   413→func (p *Parser) parseCallExpression(function ast.Expression) ast.Expression {
   414→	expr := &ast.CallExpression{
   415→		Token:     p.curToken,
   416→		Function:  function,
   417→		Arguments: []ast.Expression{},
   418→	}
   419→
   420→	expr.Arguments = p.parseExpressionList(token.RPAREN)
   421→
   422→	return expr
   423→}
