   425→// parseDotExpression parses obj.property or obj.method()
   426→func (p *Parser) parseDotExpression(left ast.Expression) ast.Expression {
   427→	// For now, treat as a simple infix operator
   428→	// Full implementation would handle member access
   429→	expr := &ast.InfixExpression{
   430→		Token:    p.curToken,
   431→		Operator: ".",
   432→		Left:     left,
   433→	}
   434→
   435→	p.nextToken()
   436→	expr.Right = p.parseExpression(CALL)
   437→
   438→	return expr
   439→}
