   441→// parseIdentifier parses variable name
   442→func (p *Parser) parseIdentifier() ast.Expression {
   443→	return &ast.Identifier{
   444→		Token: p.curToken,
   445→		Value: p.curToken.Literal,
   446→	}
   447→}
   448→
   449→// parseIntegerLiteral parses 123
   450→func (p *Parser) parseIntegerLiteral() ast.Expression {
   451→	lit := &ast.IntegerLiteral{
   452→		Token: p.curToken,
   453→	}
   454→
   455→	value, err := strconv.ParseInt(p.curToken.Literal, 0, 64)
   456→	if err != nil {
   457→		p.errors = append(p.errors, fmt.Sprintf("could not parse %q as integer", p.curToken.Literal))
   458→		return nil
   459→	}
   460→
   461→	lit.Value = value
   462→	return lit
   463→}
   464→
   465→// parseStringLiteral parses "hello"
   466→func (p *Parser) parseStringLiteral() ast.Expression {
   467→	return &ast.StringLiteral{
   468→		Token: p.curToken,
   469→		Value: p.curToken.Literal,
   470→	}
   471→}
   472→
   473→// parseBooleanLiteral parses true/false
   474→func (p *Parser) parseBooleanLiteral() ast.Expression {
   475→	return &ast.BooleanLiteral{
   476→		Token: p.curToken,
   477→		Value: p.curToken.Literal == "true",
   478→	}
   479→}
   480→
   481→// parseArrayLiteral parses [1, 2, 3]
   482→func (p *Parser) parseArrayLiteral() ast.Expression {
   483→	arr := &ast.ArrayLiteral{
   484→		Token:    p.curToken,
   485→		Elements: []ast.Expression{},
   486→	}
   487→
   488→	arr.Elements = p.parseExpressionList(token.RBRACKET)
   489→
   490→	return arr
   491→}
   492→
   493→// parseHashLiteral parses {key: value, key: value}
   494→func (p *Parser) parseHashLiteral() ast.Expression {
   495→	hash := &ast.HashLiteral{
   496→		Token: p.curToken,
   497→		Pairs: make(map[ast.Expression]ast.Expression),
   498→	}
   499→
   500→	if p.peekToken.Type == token.RBRACE {
   501→		p.nextToken()
   502→		return hash
   503→	}
   504→
   505→	for {
   506→		p.nextToken()
   507→
   508→		// Handle identifier or string keys
   509→		var key ast.Expression
   510→		switch p.curToken.Type {
   511→		case token.IDENTIFIER:
   512→			key = &ast.Identifier{
   513→				Token: p.curToken,
   514→				Value: p.curToken.Literal,
   515→			}
   516→		case token.STRING:
   517→			key = &ast.StringLiteral{
   518→				Token: p.curToken,
   519→				Value: p.curToken.Literal,
   520→			}
   521→		case token.INT:
   522→			val, _ := strconv.ParseInt(p.curToken.Literal, 0, 64)
   523→			key = &ast.IntegerLiteral{
   524→				Token: p.curToken,
   525→				Value: val,
   526→			}
   527→		default:
   528→			p.errors = append(p.errors, fmt.Sprintf("expected identifier, string, or number as hash key, got %s", p.curToken.Type))
   529→			return nil
   530→		}
   531→
   532→		if !p.expectPeek(token.COLON) {
   533→			return nil
   534→		}
   535→
   536→		p.nextToken()
   537→		value := p.parseExpression(LOWEST)
   538→		if value == nil {
   539→			return nil
   540→		}
   541→
   542→		hash.Pairs[key] = value
   543→
   544→		if p.peekToken.Type != token.COMMA {
   545→			break
   546→		}
   547→		p.nextToken() // consume comma
   548→	}
   549→
   550→	if !p.expectPeek(token.RBRACE) {
   551→		return nil
   552→	}
   553→
   554→	return hash
   555→}
   556→
   557→// parseFunctionLiteral parses func(a, b) { return a + b; }
   558→func (p *Parser) parseFunctionLiteral() ast.Expression {
   559→	lit := &ast.FunctionLiteral{
   560→		Token: p.curToken,
   561→	}
   562→
   563→	if !p.expectPeek(token.LPAREN) {
   564→		return nil
   565→	}
   566→
   567→	lit.Parameters = p.parseFunctionParameters()
   568→
   569→	if !p.expectPeek(token.LBRACE) {
   570→		return nil
   571→	}
   572→
   573→	lit.Body = p.parseBlockStatement()
   574→
   575→	return lit
   576→}
   577→
   578→// parseGroupedExpression parses (expression)
   579→func (p *Parser) parseGroupedExpression() ast.Expression {
   580→	p.nextToken()
   581→	exp := p.parseExpression(LOWEST)
   582→
   583→	if !p.expectPeek(token.RPAREN) {
   584→		return nil
   585→	}
   586→
   587→	return exp
   588→}
   589→
   590→
   591→// parseFunctionParameters parses parameter list
   592→func (p *Parser) parseFunctionParameters() []*ast.Identifier {
   593→	identifiers := []*ast.Identifier{}
   594→
   595→	if p.peekToken.Type == token.RPAREN {
   596→		p.nextToken()
   597→		return identifiers
   598→	}
   599→
   600→	p.nextToken()
   601→
   602→	ident := &ast.Identifier{
   603→		Token: p.curToken,
   604→		Value: p.curToken.Literal,
   605→	}
   606→	identifiers = append(identifiers, ident)
   607→
   608→	for p.peekToken.Type == token.COMMA {
   609→		p.nextToken()
   610→		p.nextToken()
   611→
   612→		ident := &ast.Identifier{
   613→			Token: p.curToken,
   614→			Value: p.curToken.Literal,
   615→		}
   616→		identifiers = append(identifiers, ident)
   617→	}
   618→
   619→	if !p.expectPeek(token.RPAREN) {
   620→		return nil
   621→	}
   622→
   623→	return identifiers
   624→}
   625→
   626→// parseExpressionList parses comma-separated expressions until terminator
   627→func (p *Parser) parseExpressionList(terminator token.TokenType) []ast.Expression {
   628→	list := []ast.Expression{}
   629→
   630→	if p.peekToken.Type == terminator {
   631→		p.nextToken()
   632→		return list
   633→	}
   634→
   635→	p.nextToken()
   636→	list = append(list, p.parseExpression(LOWEST))
   637→
   638→	for p.peekToken.Type == token.COMMA {
   639→		p.nextToken()
   640→		p.nextToken()
   641→		list = append(list, p.parseExpression(LOWEST))
   642→	}
   643→
   644→	if !p.expectPeek(terminator) {
   645→		return nil
   646→	}
   647→
   648→	return list
   649→}
   650→
   651→// expectPeek checks if next token is of expected type
   652→func (p *Parser) expectPeek(t token.TokenType) bool {
   653→	if p.peekToken.Type != t {
   654→		p.errors = append(p.errors, fmt.Sprintf("expected %s, got %s instead", t, p.peekToken.Type))
   655→		return false
   656→	}
   657→
   658→	p.nextToken()
   659→	return true
   660→}
   661→
   662→// curPrecedence returns precedence of current token
   663→func (p *Parser) curPrecedence() int {
   664→	if p, ok := precedences[p.curToken.Type]; ok {
   665→		return p
   666→	}
   667→
   668→	return LOWEST
   669→}
   670→
   671→// peekPrecedence returns precedence of next token
   672→func (p *Parser) peekPrecedence() int {
   673→	if p, ok := precedences[p.peekToken.Type]; ok {
   674→		return p
   675→	}
   676→
   677→	return LOWEST
   678→}
