	for _, node := range c.nodes {
		nodes = append(nodes, node)
	}
	c.mu.RUnlock()

	for _, node := range nodes {
		age := node.HeartbeatAge()
		beatThreshold := time.Duration(HeartbeatMissThreshold) * interval

		if age < interval {
			// Recent heartbeat, ensure Alive.
			if !node.IsAlive() {
				node.MarkAlive()
