	}
}

func TestStoreDelete(t *testing.T) {
	s := newStore()

	s.set("key1", []byte("value1"))
	ok := s.delete("key1")
	if !ok {
		t.Errorf("Delete should have returned true")
	}

	val, ok := s.get("key1")
	if ok || val != nil {
		t.Errorf("After delete, expected (nil, false), got (%v, %v)", val, ok)
