     1→package rpc
     2→
     3→import (
     4→	"fmt"
     5→
     6→	"github.com/kimjindol2025/freelang-go/pkg/kvstore"
     7→)
     8→
     9→// KVStoreHandler wraps a *kvstore.Cluster and exposes its operations as RPC methods.
    10→type KVStoreHandler struct {
    11→	cluster *kvstore.Cluster
    12→	codec   Codec
    13→}
    14→
    15→// NewKVStoreHandler creates a handler wrapping cluster.
    16→func NewKVStoreHandler(cluster *kvstore.Cluster, codec Codec) *KVStoreHandler {
    17→	return &KVStoreHandler{
    18→		cluster: cluster,
    19→		codec:   codec,
    20→	}
    21→}
    22→
    23→// Register installs Set, Get, Delete, Stats on server.
    24→// Method names: "KV.Set", "KV.Get", "KV.Delete", "KV.Stats"
    25→func (h *KVStoreHandler) Register(s *Server) error {
    26→	if err := s.Register("KV.Set", h.handleSet); err != nil {
    27→		return err
    28→	}
    29→	if err := s.Register("KV.Get", h.handleGet); err != nil {
    30→		return err
    31→	}
    32→	if err := s.Register("KV.Delete", h.handleDelete); err != nil {
    33→		return err
    34→	}
    35→	if err := s.Register("KV.Stats", h.handleStats); err != nil {
    36→		return err
    37→	}
    38→	return nil
    39→}
    40→
    41→// handleSet handles KV.Set: args are {key, value} (both strings).
    42→func (h *KVStoreHandler) handleSet(args []byte) ([]byte, error) {
    43→	var key string
    44→	var value string
    45→
    46→	// Decode key.
    47→	keyBuf := make([]byte, len(args))
    48→	copy(keyBuf, args)
    49→	if err := h.codec.Unmarshal(keyBuf, &key); err != nil {
    50→		return nil, fmt.Errorf("unmarshal key: %w", err)
    51→	}
    52→
    53→	// Find where value starts (after key encoding).
    54→	codec := NewBinaryCodec() // to skip key in buffer
    55→	keyEncoded, _ := codec.Marshal(key, make([]byte, 0))
    56→	if len(args) <= len(keyEncoded) {
    57→		return nil, fmt.Errorf("missing value in args")
    58→	}
    59→
    60→	valueBuf := args[len(keyEncoded):]
    61→	if err := h.codec.Unmarshal(valueBuf, &value); err != nil {
    62→		return nil, fmt.Errorf("unmarshal value: %w", err)
    63→	}
    64→
    65→	// Call cluster.Set.
    66→	if err := h.cluster.Set(key, value); err != nil {
    67→		return nil, err
    68→	}
    69→
    70→	// Return nil result.
    71→	return h.codec.Marshal(nil, make([]byte, 0))
    72→}
    73→
    74→// handleGet handles KV.Get: args is a string (key), result is a string (value).
    75→func (h *KVStoreHandler) handleGet(args []byte) ([]byte, error) {
    76→	var key string
    77→	if err := h.codec.Unmarshal(args, &key); err != nil {
    78→		return nil, fmt.Errorf("unmarshal key: %w", err)
    79→	}
    80→
    81→	// Call cluster.Get.
    82→	value, err := h.cluster.Get(key)
    83→	if err != nil {
    84→		return nil, err
    85→	}
    86→
    87→	// Marshal result.
    88→	return h.codec.Marshal(value, make([]byte, 0))
    89→}
    90→
    91→// handleDelete handles KV.Delete: args is a string (key), result is a bool.
    92→func (h *KVStoreHandler) handleDelete(args []byte) ([]byte, error) {
    93→	var key string
    94→	if err := h.codec.Unmarshal(args, &key); err != nil {
    95→		return nil, fmt.Errorf("unmarshal key: %w", err)
    96→	}
    97→
    98→	// Call cluster.Delete.
    99→	err := h.cluster.Delete(key)
   100→	success := err == nil
   101→
   102→	// Marshal result (true if deleted, false otherwise).
   103→	return h.codec.Marshal(success, make([]byte, 0))
   104→}
   105→
   106→// handleStats handles KV.Stats: no args, result is a struct with counts.
   107→func (h *KVStoreHandler) handleStats(args []byte) ([]byte, error) {
   108→	stats := h.cluster.Stats()
   109→
   110→	// Marshal as four int64 values: TotalNodes, AliveNodes, DeadNodes, TotalKeys.
   111→	result := make([]byte, 0, 256)
   112→	var err error
   113→
   114→	result, err = h.codec.Marshal(int64(stats.TotalNodes), result)
   115→	if err != nil {
   116→		return nil, err
   117→	}
   118→
   119→	result, err = h.codec.Marshal(int64(stats.AliveNodes), result)
   120→	if err != nil {
   121→		return nil, err
   122→	}
   123→
   124→	result, err = h.codec.Marshal(int64(stats.DeadNodes), result)
   125→	if err != nil {
   126→		return nil, err
   127→	}
   128→
   129→	result, err = h.codec.Marshal(int64(stats.TotalKeys), result)
   130→	if err != nil {
   131→		return nil, err
   132→	}
   133→
   134→	return result, nil
   135→}
